 useEffect(()=>{let live=true;async function load(){setLoading(true);const [s,n,b,c,sc,o,r]=await Promise.all([client.rpc('admin_dashboard_summary'),client.from('networks').select('*').order('id'),client.from('bundles').select('*').order('network').order('price'),client.from('bundle_categories').select('*').order('network').order('name'),client.from('bundle_subcategories').select('*').order('name'),client.from('orders').select('id,status,delivery_status,is_demo').eq('is_demo',false).order('created_at',{ascending:false}).limit(5000),client.from('ledger').select('reference_id').eq('kind','refund').eq('reference_type','order').limit(5000)]);if(!live)return;if(s.error)notify('Dashboard summary unavailable. Apply the latest Supabase migrations and confirm admin access.');else setSummary({...empty,...s.data});if(n.error||b.error)notify('Catalogue could not be loaded.');else{setNetworks(n.data??[]);setBundles(b.data??[])}if(c.error||sc.error){if(section==='networks')notify('Category management is unavailable. Apply migration 202610200001_bundle_categories.sql first.')}else{setCategories(c.data??[]);setSubcategories(sc.data??[])}if(!o.error)setOverviewOrders(o.data??[]);if(!r.error)setOverviewRefundedIds((r.data??[]).map(item=>String(item.reference_id)));setLoading(false)}void load();return()=>{live=false}},[client,refresh,notify,section]);
 useEffect(()=>{let live=true;async function load(){if(!['customers','orders','deposits','ledger','audit'].includes(section))return;const table=section==='customers'?'profiles':section==='orders'?'orders':section==='deposits'?'deposits':section==='ledger'?'ledger':'audit_log';let query=client.from(table).select('*').order('created_at',{ascending:false});if(section==='orders'){if(orderDates.start)query=query.gte('created_at',new Date(`${orderDates.start}T00:00:00`).toISOString());if(orderDates.end)query=query.lte('created_at',new Date(`${orderDates.end}T23:59:59.999`).toISOString())}const {data,error}=await query.limit(section==='orders'?1000:50);if(!live)return;if(error){notify(`Unable to load ${section}.`);setRows([])}else setRows(data??[])}void load();return()=>{live=false}},[client,section,refresh,notify,orderDates]);
 useEffect(()=>{let live=true;async function loadRefunds(){if(section!=='orders')return;const {data,error}=await client.from('ledger').select('reference_id').eq('kind','refund').eq('reference_type','order').limit(5000);if(!live)return;if(error){notify('Refunded order counts could not be loaded.');setRefundedOrderIds([])}else setRefundedOrderIds((data??[]).map(item=>String(item.reference_id)))}void loadRefunds();return()=>{live=false}},[client,section,refresh,notify]);
 async function toggle(table:'networks'|'bundles',id:string,active:boolean){const {error}=await client.from(table).update({is_active:!active}).eq('id',id);if(error){notify('Update was rejected by the database.');return}notify('Availability updated.');setRefresh(v=>v+1)}
 async function changePrice(id:string,price:string){const value=Number(price);if(!Number.isFinite(value)||value<0){notify('Enter a valid non-negative GHS price.');return}const {error}=await client.from('bundles').update({price:value}).eq('id',id);if(error){notify('Price update was rejected by the database.');return}notify('Bundle price updated.');setRefresh(v=>v+1)}
 async function deleteBundle(plan:Row){if(!window.confirm(`Delete ${plan.size} ${plan.network}? This also removes its Super Agent price overrides. Plans linked to past orders cannot be deleted; pause those plans instead.`))return;const {error}=await client.from('bundles').delete().eq('id',plan.id);if(error){notify(error.code==='23503'?'This plan is linked to order history and cannot be deleted. Pause it to hide it while preserving past orders.':`Could not delete plan: ${error.message}`);return}notify(`${plan.size} ${plan.network} plan deleted.`);setRefresh(v=>v+1)}
 async function saveCategory(values:{id?:string;network:DataNetwork;name:string;description:string}){const {id,...fields}=values;const query=id?client.from('bundle_categories').update({name:fields.name,description:fields.description}).eq('id',id):client.from('bundle_categories').insert(fields);const {error}=await query;if(error){notify(error.code==='23505'?'A category with that name already exists for this network.':`Could not save category: ${error.message}`);return false}notify(id?'Category updated.':'Category created.');setRefresh(v=>v+1);return true}
