 useEffect(()=>{let live=true;async function load(){setLoading(true);const [p,a,b]=await Promise.all([client.from('profiles').select('id,email').eq('role','customer').order('email').limit(1000),client.from('agent_accounts').select('user_id,agent_type,is_active,created_at').eq('agent_type','super_agent').order('created_at',{ascending:false}),client.from('bundles').select('id,network,size,price,is_active').order('network').order('price')]);if(!live)return;if(p.error||a.error||b.error){notify('Super Agent data could not load. Apply the super-agent pricing migration and confirm admin access.')}else{setCustomers(p.data??[]);setAgents(a.data??[]);setPlans(b.data??[]);if(selected&&!a.data?.some(agent=>agent.user_id===selected&&agent.is_active))setSelected('')}setLoading(false)}void load();return()=>{live=false}},[client,refresh,notify]);
 useEffect(()=>{let live=true;async function loadPrices(){if(!selected){setOverrides({});return}const {data,error}=await client.from('super_agent_bundle_prices').select('bundle_id,override_price').eq('super_agent_id',selected);if(!live)return;if(error){notify('Could not load this super agent’s price overrides.')}else setOverrides(Object.fromEntries((data??[]).map(row=>[row.bundle_id,String(row.override_price)])))}void loadPrices();return()=>{live=false}},[client,selected,refresh,notify]);
 const eligible=customers.filter(customer=>!agents.some(agent=>agent.user_id===customer.id));
 async function assign(){if(!newAgent){notify('Choose an existing customer account to register as a Super Agent.');return}const user=(await client.auth.getUser()).data.user;if(!user){notify('Administrator session expired. Sign in again.');return}const {error}=await client.from('agent_accounts').insert({user_id:newAgent,agent_type:'super_agent',assigned_by:user.id});if(error){notify(`Could not register Super Agent: ${error.message}`);return}setSelected(newAgent);setNewAgent('');notify('Super Agent account registered.');setRefresh(value=>value+1)}
