function AfaAdmin({client,notify,onPlansChanged,onCategories}:{client:SupabaseClient;notify:(message:string)=>void;onPlansChanged:()=>void;onCategories:()=>void}){
 const [plans,setPlans]=useState<Row[]>([]),[requests,setRequests]=useState<Row[]>([]),[draft,setDraft]=useState<AfaPlanDraft>(emptyAfaPlan),[editing,setEditing]=useState<string|null>(null),[query,setQuery]=useState(''),[statusFilter,setStatusFilter]=useState('all'),[loading,setLoading]=useState(true),[saving,setSaving]=useState(false),[refresh,setRefresh]=useState(0),[statusDrafts,setStatusDrafts]=useState<Record<string,string>>({});
 useEffect(()=>{let live=true;async function load(){setLoading(true);const [p,r]=await Promise.all([client.from('afa_plans').select('*').order('created_at',{ascending:false}),client.from('afa_requests').select('id,user_id,plan_id,customer_name,phone,note,id_card_number,registration_location,status,created_at,profiles(email),afa_plans(name,price)').order('created_at',{ascending:false}).limit(500)]);if(!live)return;if(p.error||r.error){notify('MTN AFA data could not load. Apply migration 202610180008_mtn_afa.sql and confirm administrator access.');setPlans([]);setRequests([])}else{setPlans(p.data??[]);setRequests((r.data??[]).map((row:Row)=>({...row,profile:Array.isArray(row.profiles)?row.profiles[0]:row.profiles,plan:Array.isArray(row.afa_plans)?row.afa_plans[0]:row.afa_plans})));}setLoading(false)}void load();return()=>{live=false}},[client,notify,refresh]);
 const visible=requests.filter(r=>(statusFilter==='all'||r.status===statusFilter)&&`${r.customer_name} ${r.phone} ${r.profile?.email??''} ${r.plan?.name??''}`.toLowerCase().includes(query.toLowerCase()));
 function editPlan(plan?:Row){setEditing(plan?.id??null);setDraft(plan?{name:plan.name,details:plan.details??'',price:String(plan.price),is_active:plan.is_active}:emptyAfaPlan)}
 async function savePlan(event:FormEvent){event.preventDefault();const price=Number(draft.price);if(!draft.name.trim()||!Number.isFinite(price)||price<0)return;setSaving(true);const payload={name:draft.name.trim(),details:draft.details.trim(),price,is_active:draft.is_active};const result=editing?await client.from('afa_plans').update(payload).eq('id',editing):await client.from('afa_plans').insert(payload);setSaving(false);if(result.error){notify(`Could not save AFA plan: ${result.error.message}`);return}notify(editing?'MTN AFA plan updated.':'MTN AFA plan created.');editPlan();setRefresh(n=>n+1);onPlansChanged()}
 async function togglePlan(plan:Row){const {error}=await client.from('afa_plans').update({is_active:!plan.is_active}).eq('id',plan.id);if(error){notify(`Could not update plan: ${error.message}`);return}notify(plan.is_active?'AFA plan paused.':'AFA plan activated.');setRefresh(n=>n+1);onPlansChanged()}
 async function updateRequest(request:Row){const status=statusDrafts[request.id]??request.status;if(status===request.status)return;const {error}=await client.from('afa_requests').update({status}).eq('id',request.id);if(error){notify(`Could not update request: ${error.message}`);return}notify(`AFA request marked ${status}.`);setRefresh(n=>n+1)}
 const counts=['pending','processing','completed','rejected'].map(status=>({status,count:requests.filter(r=>r.status===status).length}));
 return <div className="admin-afa-workbench">
 <nav className="admin-afa-nav" aria-label="MTN AFA management"><a href="#afa-requests">AFA orders</a><button type="button" onClick={onCategories}>Store categories</button><a href="#afa-plans">AFA plans</a></nav>
 <section className="admin-card admin-afa-editor" id="afa-plan-editor"><div className="admin-card-heading"><div><h2>{editing?'Edit AFA plan':'Create AFA plan'}</h2><p>Active plans appear on the customer storefront.</p></div>{editing&&<button className="admin-afa-secondary" type="button" onClick={()=>editPlan()}>Cancel</button>}</div><form className="admin-afa-form" onSubmit={savePlan}><label>Plan name<input required minLength={2} maxLength={100} value={draft.name} onChange={e=>setDraft({...draft,name:e.target.value})} placeholder="e.g. MTN AFA Registration"/></label><label>Price (GHS)<input required type="number" min="0" step="0.01" value={draft.price} onChange={e=>setDraft({...draft,price:e.target.value})} placeholder="0.00"/></label><label className="wide">Details<textarea maxLength={1000} value={draft.details} onChange={e=>setDraft({...draft,details:e.target.value})} placeholder="Explain what this service request covers."/></label><label className="admin-afa-check"><input type="checkbox" checked={draft.is_active} onChange={e=>setDraft({...draft,is_active:e.target.checked})}/> Show in storefront</label><button className="admin-afa-primary" disabled={saving}>{saving?'Saving…':editing?'Save plan':'Add plan'}</button></form></section>
 <section className="admin-card admin-afa-plans" id="afa-plans"><div className="admin-card-heading"><div><h2>MTN AFA plans</h2><p>{plans.length} plan{plans.length===1?'':'s'} configured</p></div></div>{loading?<div className="admin-empty">Loading AFA plans…</div>:plans.length?plans.map(plan=><article className="admin-afa-plan" key={plan.id}><span className="admin-afa-plan-mark"><img src={afaImage} alt="MTN AFA"/></span><div><b>{plan.name}</b><small>{plan.details||'No additional details'} · {currency(Number(plan.price))}</small><span className={`admin-afa-state ${plan.is_active?'active':'inactive'}`}>{plan.is_active?'Available to customers':'Paused'}</span></div><button className="admin-action" onClick={()=>editPlan(plan)}>Edit</button><button className="admin-action" onClick={()=>void togglePlan(plan)}>{plan.is_active?'Pause':'Activate'}</button></article>):<div className="admin-empty">Create an AFA plan to make it available to customers.</div>}</section>
 <section className="admin-card admin-afa-requests" id="afa-requests"><div className="admin-card-heading"><div><h2>Customer AFA orders</h2><p>Review requests and keep each status up to date.</p></div></div><div className="admin-afa-counts">{counts.map(item=><div key={item.status} className={`status-${item.status}`}><span>{item.status}</span><b>{item.count}</b></div>)}</div><div className="admin-afa-toolbar"><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search name, phone, email, plan…"/><select value={statusFilter} onChange={e=>setStatusFilter(e.target.value)}><option value="all">All statuses</option>{counts.map(x=><option key={x.status} value={x.status}>{x.status}</option>)}</select><span>{visible.length} request{visible.length===1?'':'s'}</span></div>{loading?<div className="admin-empty">Loading requests…</div>:visible.length?visible.map(request=><article className="admin-afa-request" key={request.id}><div className="admin-afa-request-main"><div><b>{request.customer_name}</b><span>{request.profile?.email??'Customer account'}</span></div><strong>{request.phone}</strong><div><b>{request.plan?.name??'AFA plan'}</b><span>{currency(Number(request.plan?.price??0))}</span></div><time>{new Date(request.created_at).toLocaleString()}</time>{request.note&&<p>{request.note}</p>}<details className="admin-afa-private"><summary>Registration details</summary><p><b>Ghana Card:</b> {request.id_card_number||"Not provided"}<br/><b>Location:</b> {request.registration_location||"Not provided"}</p></details></div><div className="admin-afa-request-actions"><span className={`admin-afa-state ${request.status}`}>{request.status}</span><select aria-label={`Status for ${request.customer_name}`} value={statusDrafts[request.id]??request.status} onChange={e=>setStatusDrafts({...statusDrafts,[request.id]:e.target.value})}>{counts.map(x=><option key={x.status} value={x.status}>{x.status}</option>)}</select><button className="admin-afa-primary" disabled={(statusDrafts[request.id]??request.status)===request.status} onClick={()=>void updateRequest(request)}>Update status</button></div></article>):<div className="admin-empty">{query||statusFilter!=='all'?'No requests match these filters.':'No AFA requests have been submitted yet.'}</div>}</section></div>
}
function Records({section,rows,loading}:{section:Exclude<Section,'overview'|'catalog'|'networks'>;rows:Row[];loading:boolean}){if(loading)return <section className="admin-card admin-record-card"><div className="admin-empty">Loading {section}…</div></section>;return <section className="admin-card admin-record-card"><div className="admin-card-heading"><div><h2>{sections.find(x=>x[0]===section)?.[1]}</h2><p>Latest 50 records · data access enforced by database policies.</p></div></div>{rows.length?<div className="admin-record-list">{rows.map(r=><div className="admin-record-row" key={r.id??r.user_id??r.created_at}><div className="admin-record-main"><b>{section==='customers'?r.email||r.id:section==='orders'?`${r.recipient_phone} · ${r.bundle_id}`:section==='deposits'?`${r.provider} · ${currency(Number(r.amount))}`:section==='ledger'?`${r.kind} · ${currency(Number(r.amount))}`:`${r.action} · ${r.entity}`}</b><small>{section==='orders'||section==='deposits'?r.status:section==='audit'?r.entity_id:r.user_id??r.id}</small></div><time>{r.created_at?new Date(r.created_at).toLocaleString():'—'}</time></div>)}</div>:<div className="admin-empty">No {section} records yet.</div>}</section>}

function AgentRequestsAdmin({client,notify}:{client:SupabaseClient;notify:(message:string)=>void}){
 const [numbers,setNumbers]=useState<Row[]>([]),[tickets,setTickets]=useState<Row[]>([]),[loading,setLoading]=useState(true),[busyId,setBusyId]=useState('');
 async function load(){setLoading(true);const [n,t]=await Promise.all([client.from('agent_number_submissions').select('*').order('created_at',{ascending:false}).limit(500),client.from('agent_support_tickets').select('*').order('created_at',{ascending:false}).limit(200)]);if(n.error||t.error){notify('Agent requests could not load. Apply migration 202610280001_agent_portal_tools.sql and confirm admin access.')}setNumbers(n.data??[]);setTickets(t.data??[]);setLoading(false)}
 useEffect(()=>{void load()},[client]);
 async function setNumberStatus(row:Row,status:'approved'|'rejected'){setBusyId(row.id);const {error}=await client.from('agent_number_submissions').update({status,reviewed_at:new Date().toISOString(),reviewed_by:(await client.auth.getUser()).data.user?.id}).eq('id',row.id);setBusyId('');if(error){notify(`Could not update number review: ${error.message}`);return}notify(`Number marked ${status}.`);void load()}
 async function setTicketStatus(row:Row,status:string){setBusyId(row.id);const {error}=await client.from('agent_support_tickets').update({status,updated_at:new Date().toISOString()}).eq('id',row.id);setBusyId('');if(error){notify(`Could not update support request: ${error.message}`);return}notify('Support request status updated.');void load()}
 return <div className="admin-agent-requests"><section className="admin-card"><div className="admin-card-heading"><div><h2>Agent number approvals</h2><p>Approve or reject numbers submitted by active agents.</p></div><span className="admin-config-badge">{numbers.filter(row=>row.status==='pending').length} pending</span></div>{loading?<div className="admin-empty">Loading agent requests…</div>:numbers.length?numbers.map(row=><article className="admin-agent-request-row" key={row.id}><div><b>{row.phone_number}</b><small>Agent {row.agent_id} · submitted {new Date(row.created_at).toLocaleString()}</small></div><span className={`agent-order-status stage-${row.status}`}>{row.status}</span>{row.status==='pending'&&<div className="admin-agent-request-actions"><button disabled={busyId===row.id} onClick={()=>void setNumberStatus(row,'approved')}>Approve</button><button disabled={busyId===row.id} onClick={()=>void setNumberStatus(row,'rejected')}>Reject</button></div>}</article>):<div className="admin-empty">No agent number requests.</div>}</section><section className="admin-card"><div className="admin-card-heading"><div><h2>Agent support requests</h2><p>Review complaints and update their status.</p></div><span className="admin-config-badge">{tickets.filter(row=>row.status==='open').length} open</span></div>{loading?<div className="admin-empty">Loading support requests…</div>:tickets.length?tickets.map(row=><article className="admin-agent-request-row" key={row.id}><div><b>{row.subject}</b><small>Agent {row.agent_id} · {new Date(row.created_at).toLocaleString()}</small><p>{row.message}</p></div><select aria-label="Support request status" value={row.status} disabled={busyId===row.id} onChange={event=>void setTicketStatus(row,event.target.value)}><option value="open">Open</option><option value="in_progress">In progress</option><option value="resolved">Resolved</option><option value="closed">Closed</option></select></article>):<div className="admin-empty">No support requests.</div>}</section></div>
}
